#include <iostream>

// Node structure
struct Node {
    int data;
    Node* next;
};

// Function to reverse a linked list
Node* reverseLinkedList(Node* head) {
    Node* prev = NULL;
    Node* current = head;
    Node* next = NULL;

    while (current != NULL) {
        next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }

    return prev;
}

// Function to print a linked list
void printLinkedList(Node* head) {
    while (head != NULL) {
        std::cout << head->data << " ";
        head = head->next;
    }
    std::cout << std::endl;
}

int main() {
    // Create a sample linked list: 1 -> 2 -> 3 -> 4 -> 5
    Node* head = new Node();
    head->data = 1;

    Node* temp = head;
    for (int i = 2; i <= 5; i++) {
        Node* newNode = new Node();
        newNode->data = i;
        temp->next = newNode;
        temp = temp->next;
    }

    temp->next = NULL; // Set the last node's next pointer to NULL

    std::cout << "Original Linked List: ";
    printLinkedList(head);

    head = reverseLinkedList(head);

    std::cout << "Reversed Linked List: ";
    printLinkedList(head);

    return 0;
}
